WITH flattened_attrs AS (SELECT id, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT id, entry_price, LEAD(entry_price, 2) OVER (ORDER BY lowest_price, id) AS next_entry_price, FIRST_VALUE(lowest_price, TRUE) OVER (ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_lowest_price FROM flattened_attrs
